extension on _TranslationsKo {
	dynamic _flatMapFunction(String path) {
		switch (path) {
			case 'app.appBootstrapper.failedToInitializeMessage': return ({required Object error}) => '앱 초기화에 실패했어요:\n\n${error}';
			case 'character.promptPrefixDialog.styleKeywordsLabel': return '스타일 키워드';
			case 'character.promptPrefixDialog.imageTitle': return '이미지 스타일';
			case 'character.promptPrefixDialog.imageDescription': return '이 캐릭터의 모든 이미지 생성 프롬프트 앞에 붙어요 (예: "애니메이션 스타일, 선명한 색감").';
			case 'character.promptPrefixDialog.imageHint': return '애니메이션 스타일, 선명한 색감';
			case 'character.promptPrefixDialog.videoTitle': return '비디오 스타일';
			case 'character.promptPrefixDialog.videoDescription': return '이 캐릭터의 모든 비디오 생성 프롬프트 앞에 붙어요 (예: "영화적, 얕은 피사계 심도, 24fps 필름 그레인"). 비디오 모델은 움직임과 카메라 관련 표현에 잘 반응하니 짧게 유지하세요.';
			case 'character.promptPrefixDialog.videoHint': return '영화적, 얕은 피사계 심도';
			case 'character.cardEditApproval.denyAll': return '모두 거부';
			case 'character.cardEditApproval.approveAll': return '모두 승인';
			case 'character.cardEditApproval.confirm': return '확인';
			case 'character.cardEditApproval.dialogTitle': return '어시스턴트가 변경을 제안했어요';
			case 'character.cardEditApproval.dontAskAgainFor': return ({required Object modality}) => '${modality}에 대해 다시 묻지 않기';
			case 'character.cardEditApproval.modalityLabel.edits': return '편집';
			case 'character.cardEditApproval.modalityLabel.additions': return '추가';
			case 'character.cardEditApproval.modalityLabel.deletions': return '삭제';
			case 'character.cardEditApproval.modalityVerb.edit': return '편집';
			case 'character.cardEditApproval.modalityVerb.addition': return '추가';
			case 'character.cardEditApproval.modalityVerb.deletion': return '제거';
